      lawOk: "Xong",
      lawSavedOne: (name) => `\u2714 \u0110\xE3 l\u01B0u ch\u1EC9nh s\u1EEDa lu\u1ED3ng \xAB${name}\xBB. Lu\u1ED3ng v\u1EABn l\xE0 b\u1EA3n nh\xE1p \u2014 b\u1EA5m \xABDuy\u1EC7t\xBB \u0111\u1EC3 \xE1p d\u1EE5ng.`,
      lawSynced: (added, removed, renamed) => added + removed + renamed === 0 ? "\u0110\xE3 r\xE0 l\u1EA1i c\u01A1 c\u1EA5u: kh\xF4ng c\xF3 ph\xF2ng n\xE0o th\xEAm m\u1EDBi, kh\xF4ng c\xF2n hay \u0111\u1ED5i t\xEAn so v\u1EDBi l\u1EA7n r\xE0 tr\u01B0\u1EDBc." : `\u0110\xE3 r\xE0 l\u1EA1i c\u01A1 c\u1EA5u: ${added} ph\xF2ng m\u1EDBi, ${removed} ph\xF2ng kh\xF4ng c\xF2n, ${renamed} ph\xF2ng \u0111\u1ED5i t\xEAn.`,
      lawApprovedOne: (name) => `\u2714 \u0110\xE3 DUY\u1EC6T lu\u1ED3ng \xAB${name}\xBB \u2014 lu\u1ED3ng \u0111\xE3 c\xF3 hi\u1EC7u l\u1EF1c.`,
      lawRejectedOne: (name) => `\u0110\xE3 T\u1EEA CH\u1ED0I lu\u1ED3ng \xAB${name}\xBB.`,
      lawApprovedAll: (n, skippedInvalid = 0) => `\u2714 \u0110\xE3 duy\u1EC7t ${n} lu\u1ED3ng \u2014 c\xE1c lu\u1ED3ng \u0111\xE3 c\xF3 hi\u1EC7u l\u1EF1c.${skippedInvalid > 0 ? ` B\u1ECF qua ${skippedInvalid} lu\u1ED3ng c\xF3 gi\xE1 tr\u1ECB kh\xF4ng h\u1EE3p l\u1EC7 (SLA, t\xEAn\u2026): h\xE3y b\u1EA5m \xABS\u1EEDa\xBB r\u1ED3i duy\u1EC7t l\u1EA1i.` : ""}`,
      lawGenerated: (n, by, skippedRejected = 0) => {
        const note = skippedRejected > 0 ? ` ${skippedRejected} g\u1EE3i \xFD b\u1EA1n \u0111\xE3 t\u1EEB ch\u1ED1i tr\u01B0\u1EDBc \u0111\xF3 n\xEAn kh\xF4ng \u0111\u1EC1 xu\u1EA5t l\u1EA1i (mu\u1ED1n c\xF3 th\xEC th\xEAm tay \u1EDF \xABB\xE0n giao gi\u1EEFa c\xE1c ph\xF2ng\xBB).` : "";
        if (n === 0) return `Kh\xF4ng c\xF3 g\u1EE3i \xFD m\u1EDBi (c\xE1c lu\u1ED3ng khung \u0111\xE3 \u0111\u1EE7 ho\u1EB7c \u0111ang ch\u1EDD duy\u1EC7t).${note}`;
        const parts = [["report_up", "b\xE1o c\xE1o l\xEAn"], ["directive_down", "ch\u1EC9 \u0111\u1EA1o xu\u1ED1ng"], ["review", "r\xE0 so\xE1t \u0111\u1ED9c l\u1EADp"], ["peer", "ph\u1ED1i h\u1EE3p ngang"]].filter(([k]) => by[k]).map(([k, label]) => `${by[k]} ${label}`);
        return `\u0110\xE3 t\u1EA1o ${n} g\u1EE3i \xFD m\u1EDBi${parts.length ? ` (${parts.join(", ")})` : ""}. Xem \u1EDF danh s\xE1ch b\xEAn d\u01B0\u1EDBi.${note}`;
      },
      lawNoLineNote: "Lu\u1ED3ng \u0111\xE3 duy\u1EC7t ch\u1EC9 hi\u1EC7n th\xE0nh \u0111\u01B0\u1EDDng tr\xEAn s\u01A1 \u0111\u1ED3 khi \u0111\xE3 c\xF3 vi\u1EC7c th\u1EADt ch\u1EA1y qua gi\u1EEFa hai ph\xF2ng.",
      lawWhatTitle: "C\u1EA5u h\xECnh lu\u1EADt d\xF9ng \u0111\u1EC3 l\xE0m g\xEC, hi\u1EC7n \u1EDF \u0111\xE2u?",
      lawWhatUse: "D\xF9ng \u0111\u1EC3: khai b\xE1o c\xE1c lo\u1EA1i s\u1EF1 ki\u1EC7n b\xE0n giao gi\u1EEFa c\xE1c ph\xF2ng \u2014 ph\xF2ng n\xE0o \u0111\u01B0\u1EE3c g\u1EEDi, ph\xF2ng n\xE0o nh\u1EADn, m\u1EE9c r\u1EE7i ro v\xE0 h\u1EA1n tr\u1EA3 l\u1EDDi. Khi m\u1ED9t nh\xE2n vi\xEAn g\u1EEDi s\u1EF1 ki\u1EC7n, h\u1EC7 th\u1ED1ng ki\u1EC3m lu\u1EADt (lo\u1EA1i s\u1EF1 ki\u1EC7n ph\u1EA3i c\xF3, ng\u01B0\u1EDDi g\u1EEDi ph\u1EA3i thu\u1ED9c ph\xF2ng \u0111\u01B0\u1EE3c ph\xE9p g\u1EEDi), theo d\xF5i h\u1EA1n tr\u1EA3 l\u1EDDi r\u1ED3i m\u1EDF th\u1EBB cho ng\u01B0\u1EDDi nh\u1EADn.",
      lawWhatShown: "Hi\u1EC7n \u1EDF: s\u01A1 \u0111\u1ED3 \xABM\u1EA1ng l\u01B0\u1EDBi giao vi\u1EC7c\xBB ph\xEDa tr\xEAn (\u0111\u01B0\u1EDDng m\u1EDD khi ch\u01B0a c\xF3 vi\u1EC7c, \u0111\u01B0\u1EDDng \u0111\u1EADm khi \u0111\xE3 c\xF3 vi\u1EC7c th\u1EADt) v\xE0 tab \xABB\xE0n giao gi\u1EEFa c\xE1c ph\xF2ng\xBB.",
      lawWhatNot: "Kh\xF4ng l\xE0m: lu\u1EADt kh\xF4ng t\u1EF1 sinh vi\u1EC7c, v\xE0 kh\xF4ng cho ph\xE9p nh\xE2n vi\xEAn giao th\u1EBB th\u1EB3ng cho ph\xF2ng kh\xE1c \u2014 vi\u1EC7c \u0111\xF3 do \xABGiao th\u1EBB vi\u1EC7c cho ng\u01B0\u1EDDi kh\xE1c\xBB \u1EDF Ch\xEDnh s\xE1ch \u2192 Li\xEAn l\u1EA1c gi\u1EEFa nh\xE2n vi\xEAn quy\u1EBFt \u0111\u1ECBnh. Lu\u1EADt c\u0169ng kh\xF4ng li\xEAn quan t\u1EDBi \xABC\u1EA5u h\xECnh quy tr\xECnh\xBB.",
      lawGenerateScope: "\xABT\u1EA1o g\u1EE3i \xFD lu\u1ED3ng\xBB ch\u1EC9 sinh khung: b\xE1o c\xE1o l\xEAn, ch\u1EC9 \u0111\u1EA1o xu\u1ED1ng v\xE0 \u0111\u01B0a vi\u1EC7c qua Tu\xE2n th\u1EE7/Ki\u1EC3m to\xE1n. Quan h\u1EC7 ph\u1ED1i h\u1EE3p ngang gi\u1EEFa c\xE1c ph\xF2ng ch\u1EC9 sinh khi b\u1EA1n ch\u1ECDn ph\xF2ng \u1EDF m\u1EE5c b\xEAn d\u01B0\u1EDBi.",
      lawPeerToggle: "Ph\u1ED1i h\u1EE3p ngang gi\u1EEFa c\xE1c ph\xF2ng (t\xF9y ch\u1ECDn)",
      lawPeerHint: "Ch\u1ECDn t\u1EEB 2 ph\xF2ng tr\u1EDF l\xEAn r\u1ED3i b\u1EA5m t\u1EA1o: h\u1EC7 th\u1ED1ng ch\u1EC9 sinh lu\u1ED3ng ph\u1ED1i h\u1EE3p gi\u1EEFa c\xE1c ph\xF2ng c\xF9ng c\u1EA5p m\xE0 b\u1EA1n \u0111\xE3 ch\u1ECDn (kh\xF4ng sinh cho m\u1ECDi c\u1EB7p ph\xF2ng).",
      lawPeerGenerate: (n) => `T\u1EA1o g\u1EE3i \xFD ph\u1ED1i h\u1EE3p cho ${n} ph\xF2ng \u0111\xE3 ch\u1ECDn`,
      lawConfirmApproveAll: (n) => `Duy\u1EC7t to\xE0n b\u1ED9 ${n} \u0111\u1EC1 xu\u1EA5t quy \u0111\u1ECBnh lu\u1ED3ng \u0111ang ch\u1EDD ngay b\xE2y gi\u1EDD? C\xE1c quy \u0111\u1ECBnh c\xF3 hi\u1EC7u l\u1EF1c ngay cho lu\u1ED3ng c\xF4ng vi\u1EC7c gi\u1EEFa c\xE1c ph\xF2ng.`,
